from hashlib import md5
from six import with_metaclass
from abc import ABCMeta, abstractproperty


class MessageBase(with_metaclass(ABCMeta, object)):
    @abstractproperty
    def xml_template(self):
        raise NotImplementedError

    def get_xml(self, *args, **kwargs):
        return self.xml_template.format(*args, **kwargs)


class Message(MessageBase):
    xml_template = """<?xml version="1.0" encoding="UTF-8" ?>
                           <SOAP:Envelope xmlns:SOAP="http://schemas.xmlsoap.org/soap/envelope/">
                               <SOAP:Header>
                                   <header xmlns="xmlapi_1.0">
                                       <security>
                                           <user>{username}</user>
                                           <password>{password}</password>
                                       </security>
                                       <requestID>client1:0</requestID>
                                   </header>
                               </SOAP:Header>
                               <SOAP:Body>
                               {body}
                               </SOAP:Body>
                           </SOAP:Envelope>"""

    def __init__(self, username, password, body=None):
        """

        :param str username:
        :param str password:
        :param MessageBase body:  #TODO: body should be string type and allow user to directly pass an str body
        """
        self.username = username
        self.password = md5(password.encode('utf-8')).hexdigest()
        self.body = body

    def get_xml(self, body=None):
        if self.body is None and body is None:
            raise ValueError("Please provide body for MessageSchema, either via constructor or as parameter in get_xml")

        if self.body is None:
            msg_body = body
        else:
            msg_body = self.body

        return super(Message, self).get_xml(
            username=self.username,
            password=self.password,
            body=msg_body.get_xml()
        )


class GetAlarms(MessageBase):
    xml_template = '''<fm.FaultManager.getAlarms xmlns="xmlapi_1.0">
                      </fm.FaultManager.getAlarms>'''


class ResetMrbts(MessageBase):
    xml_template = '''<racgnb.MRBTS.mrbtsHwReset xmlns="xmlapi_1.0">
                        <deployer>immediate</deployer>
                        <instanceFullName>{instance_full_name}</instanceFullName>
                      </racgnb.MRBTS.mrbtsHwReset>'''

    def __init__(self, instance_full_name):
        self.instance_full_name = instance_full_name

    def get_xml(self):
        return super(ResetMrbts, self).get_xml(instance_full_name=self.instance_full_name)


class GetModuleInfo(MessageBase):
    xml_template = '''<find xmlns="xmlapi_1.0">
                          <fullClassName>{full_class_name}</fullClassName>
                          <filter class="netw.NetworkElement">
                              <equal name="siteId" value="{site_id}"/>
                              {filter_id_str}
                          </filter>
                      </find>'''

    def __init__(self, full_class_name, site_id, module_id):
        self.full_class_name = full_class_name
        self.site_id = site_id
        self.module_id = module_id

    def get_xml(self):
        if self.module_id is not None:
            filter_id_str = '''<equal name="id" value="{}"/>'''.format(self.module_id)
        else:
            filter_id_str = ''
        return super(GetModuleInfo, self).get_xml(full_class_name=self.full_class_name,
                                                  site_id=self.site_id,
                                                  filter_id_str=filter_id_str)


class ChangeNrCellAdministrativeState(MessageBase):
    xml_template = '''<generic.GenericObject.configureInstanceWithResult xmlns="xmlapi_1.0">
                          <deployer>immediate</deployer>
                          <synchronousDeploy>true</synchronousDeploy>
                          <distinguishedName>{distinguished_name}</distinguishedName>
                          <includeChildren>false</includeChildren>
                          <configInfo>
                            <racgnb.NRCELL>
                              <actionMask>
                                <bit>modify</bit>
                              </actionMask>
                              <administrativeState>{state}</administrativeState>
                            </racgnb.NRCELL>
                          </configInfo>
                        </generic.GenericObject.configureInstanceWithResult>'''

    def __init__(self, distinguished_name, state):
        self.distinguished_name = distinguished_name
        self.state = state

    def get_xml(self):
        return super(ChangeNrCellAdministrativeState, self).get_xml(distinguished_name=self.distinguished_name,
                                                                    state=self.state)


class SetToActive(MessageBase):
    def __init__(self, bts_id):
        self.bts_id = bts_id

    @property
    def xml_template(self):
        return '''<netw.NetworkElement.setToActive xmlns="xmlapi_1.0">
                      <deployer>immediate</deployer>
                      <instanceFullName>network:{bts_id}</instanceFullName>
                      </netw.NetworkElement.setToActive>'''.format(bts_id=self.bts_id)


